@UserQuestion_9341040ddb73 NVARCHAR(MAX),
@Description_9341040ddb73 NVARCHAR(MAX),
@SQL_9341040ddb73 NVARCHAR(MAX),
@TechnicalDescription_9341040ddb73 NVARCHAR(MAX),
@OriginalSQL_9341040ddb73 NVARCHAR(MAX),
@Feedback_9341040ddb73 NVARCHAR(MAX),
@Status_9341040ddb73 NVARCHAR(15),
@QualityRank_9341040ddb73 INT,
@ExecutionCostRank_9341040ddb73 INT,
@UsesTemplate_9341040ddb73 BIT,
@AuditQueryRuns_9341040ddb73 BIT,
@CacheEnabled_9341040ddb73 BIT,
