@ExternalDataSourceID_9341040ddb73 UNIQUEIDENTIFIER,
@IsMaterialized_9341040ddb73 BIT,
@Configuration_9341040ddb73 NVARCHAR(MAX),
@EmbeddingVectorBinary_9341040ddb73 VARBINARY(MAX),
@ApprovalComments_9341040ddb73 NVARCHAR(MAX),
@ApprovedByUserID_9341040ddb73 UNIQUEIDENTIFIER,
@ApprovedAt_9341040ddb73 DATETIMEOFFSET,
@ApprovedFingerprint_9341040ddb73 NVARCHAR(100),
@ExtractedSQLHash_9341040ddb73 NVARCHAR(64),
@ExtractionStatus_9341040ddb73 NVARCHAR(20),
@ExtractionMessage_9341040ddb73 NVARCHAR(MAX)
SET
  @ID_9341040ddb73 = '6C0A1000-0001-4000-A000-000000000010'
SET
  @Name_9341040ddb73 = N'Common: Directory People Per Day'
SET
  @CategoryID_9341040ddb73 = (
    SELECT
      [ID]
    FROM
      [${mjSchema}].[QueryCategory]
    WHERE
      LOWER([Name]) = LOWER(N'Common')
  )
SET
  @UserQuestion_9341040ddb73 = N'How many people were added on each of the last seven business days?'
SET
  @Description_9341040ddb73 = N'The directory dashboard''s "people added" bars: one row with a count for each of the last seven business days, today first.'
SET
  @SQL_9341040ddb73 = N'-- People added on each of the last seven BUSINESS days, as one row: PeopleAddedD0 is today,
-- PeopleAddedD6 six days ago. Read by the directory dashboard''s "people added" bars.
--
-- __mj_CreatedAt is a UTC instant; fnBusinessDayOf turns it into the day it was in the business
-- time zone, the same zone fnBusinessToday() reads for "today" (bc-aidp-next-golive#168). A UTC
-- day put Thursday evening''s signups in Friday''s bar for anyone in the Americas.
--
-- Kept apart from Common: Directory Dashboard Summary on purpose. fnBusinessDayOf is a scalar
-- function SQL Server cannot inline (it converts time zones), so it runs once per row and makes
-- any statement that calls it single-threaded. Here it runs only for the rows the WHERE keeps
-- (the last eight days); in the summary it slowed every count with it.
-- No inline AT TIME ZONE: MJ''s SQL parser cannot read it.
--
-- Single SELECT (no DECLARE / temp tables) so RunQuery can wrap it.
SELECT
    ISNULL(SUM(CASE WHEN d.CreatedDay = bt.Today THEN 1 ELSE 0 END), 0) AS PeopleAddedD0,
    ISNULL(SUM(CASE WHEN d.CreatedDay = DATEADD(DAY, -1, bt.Today) THEN 1 ELSE 0 END), 0) AS PeopleAddedD1,
    ISNULL(SUM(CASE WHEN d.CreatedDay = DATEADD(DAY, -2, bt.Today) THEN 1 ELSE 0 END), 0) AS PeopleAddedD2,
    ISNULL(SUM(CASE WHEN d.CreatedDay = DATEADD(DAY, -3, bt.Today) THEN 1 ELSE 0 END), 0) AS PeopleAddedD3,
    ISNULL(SUM(CASE WHEN d.CreatedDay = DATEADD(DAY, -4, bt.Today) THEN 1 ELSE 0 END), 0) AS PeopleAddedD4,
    ISNULL(SUM(CASE WHEN d.CreatedDay = DATEADD(DAY, -5, bt.Today) THEN 1 ELSE 0 END), 0) AS PeopleAddedD5,
    ISNULL(SUM(CASE WHEN d.CreatedDay = DATEADD(DAY, -6, bt.Today) THEN 1 ELSE 0 END), 0) AS PeopleAddedD6
FROM [${flyway:defaultSchema}].[fnBusinessToday]() AS bt
LEFT JOIN
(
    SELECT [${flyway:defaultSchema}].[fnBusinessDayOf](x.__mj_CreatedAt) AS CreatedDay
    FROM [${flyway:defaultSchema}].[vwPeople] x
    WHERE x.__mj_CreatedAt >= DATEADD(DAY, -8, SYSDATETIMEOFFSET())
) d ON 1 = 1
;
'
SET
  @TechnicalDescription_9341040ddb73 = N'Grain: one row. PeopleAddedD0 (today) to PeopleAddedD6: vwPeople rows whose __mj_CreatedAt falls on that business day, by fnBusinessDayOf against fnBusinessToday().Today (the BizApps business time zone). fnBusinessDayOf runs only on rows created in the last eight days. Separate from Common: Directory Dashboard Summary because fnBusinessDayOf cannot be inlined, which makes any statement that calls it single-threaded. No template parameters.'
SET
  @Status_9341040ddb73 = N'Approved'
SET
  @QualityRank_9341040ddb73 = 9
SET
  @ExecutionCostRank_9341040ddb73 = 1
SET
  @UsesTemplate_9341040ddb73 = 0
SET
  @AuditQueryRuns_9341040ddb73 = 0
SET
  @CacheEnabled_9341040ddb73 = 0
SET
  @Reusable_9341040ddb73 = 0
SET
  @IsMaterialized_9341040ddb73 = 0
SET
  @ApprovedByUserID_9341040ddb73 = 'ECAFCCEC-6A37-EF11-86D4-000D3A4E707E'
SET
