-- Save MJ: Queries (core SP call only)
DECLARE @ApprovedFingerprint_9341040ddb73 NVARCHAR(100),
@ID_9341040ddb73 UNIQUEIDENTIFIER
SET
  @ApprovedFingerprint_9341040ddb73 = N'43014bbbb47098fabc59adfd9eb9c356257f2abd80af74094c057457e7249347'
SET
  @ID_9341040ddb73 = '6C0A1000-0001-4000-A000-000000000010'
-- Set only while the query has no approved fingerprint, so a host's own approval is kept.
IF EXISTS (SELECT 1 FROM [${mjSchema}].[Query]
           WHERE [ID] = @ID_9341040ddb73 AND [ApprovedFingerprint] IS NULL)
EXEC [${mjSchema}].spUpdateQuery @ApprovedFingerprint = @ApprovedFingerprint_9341040ddb73,
  @ID = @ID_9341040ddb73;

GO
